<?php $streamcreedRtmp = is_array($rRTMPInfo ?? null) ? $rRTMPInfo : []; $streamcreedLive = $streamcreedRtmp['server']['application']['live']['stream'] ?? []; if (!is_array($streamcreedLive)) $streamcreedLive = $streamcreedLive ? [$streamcreedLive] : []; ?>
<section class="sc-settings"><div class="sc-page-heading"><div><p class="sc-eyebrow">System</p><h1>RTMP Management</h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="rtmp_monitor?admin_ui=legacy"><i class="fe-corner-up-left" aria-hidden="true"></i> Open full monitor</a></div></div><div class="sc-data-panel"><div class="sc-settings-list"><div class="sc-settings-row"><span>RTMP process</span><strong><?php echo htmlspecialchars((string) ($streamcreedRtmp['pid'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>NGINX / FLV</span><strong><?php echo htmlspecialchars((string) ($streamcreedRtmp['nginx_version'] ?? '—') . ' / ' . (string) ($streamcreedRtmp['nginx_http_flv_version'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>Input / output</span><strong><?php echo number_format((float) ($streamcreedRtmp['bw_in'] ?? 0) / 1000000, 2); ?> / <?php echo number_format((float) ($streamcreedRtmp['bw_out'] ?? 0) / 1000000, 2); ?> Mbps</strong></div><div class="sc-settings-row"><span>Live RTMP streams</span><strong><?php echo number_format(count($streamcreedLive)); ?></strong></div></div></div><p class="sc-settings-note"><i class="fe-info" aria-hidden="true"></i> Stream controls and server selection remain available in the full RTMP monitor.</p></section>
